definition.raw:
A \textbf{$(\scr{C}, \scr{D})$-bimodule} is a functor $\scr{M}\colon  \scr{C}^{\text{op}} \sma \scr{D} \to \operatorname{Sp}$. That is, $\scr{M}$ is a collection of spectra $\scr{M}(c, d)$ for $c \in \scr{C}$, $d \in \scr{D}$ together with maps
  \begin{align*}
    &\scr{C}(c, c') \sma \scr{M}(c', d) \to \scr{M}(c, d)\\
    &\scr{M}(c, d) \sma \scr{D}(d,d') \to \scr{M}(c, d') 
  \end{align*}
  An $(\scr{C}, \scr{D})$-bimodule is {\bf pointwise cofibrant} if $\scr{M}(c, d)$ is cofibrant. A {\bf morphism} of $(\scr{C}, \scr{D})$-bimodules $\scr{M} \to \scr{M}'$ is a collection of maps $\scr{M}(c, d) \to \scr{M}'(c, d)$ which commute with the appropriate structure.

\label{def:shadow}
  Let $\scr{B}$ be a bicategory.  A \textbf{shadow functor} for $\scr{B}$
  consists of functors
  \[
   \sh{-}\colon  \scr{B}(C,C) \to \mathbf{T}
  \]
  for each object $C$ of $\scr{B}$ and some fixed category $\mathbf{T}$, equipped
  with a natural isomorphism
  \[
   \theta\colon \sh{M\odot N}\xrightarrow{\cong} \sh{N\odot M}
  \]
  for $M\in \scr{B}(C, D)$ and $N\in \scr{B}(D, C)$ such that the following
  diagrams commute whenever they make sense:
  \[\xymatrix{
    \sh{(M\odot N)\odot P} \ar[r]^\theta \ar[d]_{\sh{a}} &
    \sh{P \odot (M\odot N)} \ar[r]^{\sh{a}} &
    \sh{(P\odot M) \odot N}
    \\
    \sh{M\odot (N\odot P)} \ar[r]^\theta 
    & \sh{(N\odot P)\odot M} \ar[r]^{\sh{a}} 
   & \sh{N\odot (P\odot M)}\ar[u]_\theta 
  }\]
  \[\xymatrix{
    \sh{M\odot U_C} \ar[r]^\theta \ar[dr]_{\sh{r}} &
    \sh{U_C\odot M} \ar[d]^{\sh{l}} \ar[r]^\theta &
    \sh{M\odot U_C} \ar[dl]^{\sh{r}}
    \\
    &\sh{M}}\]

\cite{p:thesis}\label{defn:trace}
  Let $\scr{B}$ be a bicategory with a shadow functor and $(M,N)$ be a dual pair.
  The \textbf{trace} of a 2-cell $f\colon Q\odot M\rightarrow M\odot P$ is the composite:
  \[
   \sh{Q}\cong \sh{Q\odot U_C}\xrightarrow{\sh{\id_Q\odot\eta}}
  \sh{Q\odot M\odot N} \xrightarrow{\sh{f\odot\id_N}}
  \sh{M\odot P\odot N} \xrightarrow{\theta}
  \sh{N\odot M\odot P} \xrightarrow{\sh{\epsilon \odot \id_P}}
  \sh{U_D\odot P}\cong   \sh{P}.
  \]
The trace of a 2-cell $g\colon N\odot Q\to P\odot N$ is 
  \[
   \sh{Q}\cong \sh{U_C\odot Q}\xrightarrow{\sh{\eta\odot\id_Q}}
  \sh{M\odot N\odot Q} \xrightarrow{\sh{\id_M\odot g}}
  \sh{M\odot P\odot N} \xrightarrow{\theta}
  \sh{P\odot N\odot M} \xrightarrow{\sh{\id_P \odot \epsilon}}
    \sh{P\odot U_D}\cong   \sh{P}.
  \]

\label{defn:euler_characteristic}
  If $M\in \scr{B}(C,D)$ and $M$ is right dualizable, the \textbf{Euler characteristic} (\cref{fig:euler_char}) is the trace of the identity 2-cell of $M$ and is a map \[\sh{U_C}\to \sh{U_D}.\]   
If $N$ is the right dual of $M$, $\chi(M)=\chi(N)$.

\label{defn:morita_equivalence}
A pair of one cells $M\in \scr{B}(C,D)$ and $N\in \scr{B}(D,C)$ is a {\bf Morita equivalence} if $(M,N)$ and $(N,M)$ are dual pairs and
the coevaluation and evaluation maps for each dual pair are inverses.  That is, if $\eta_{(M,N)}$ and $\epsilon_{(M,N)}$ are the coevaluation and evaluation 
for $(M,N)$ and $\eta_{(N,M)}$ and $\epsilon_{(N,M)}$ are the coevaluation and evaluation 
for $(N,M)$ then
\begin{align*}
 \eta_{(N,M)}\circ \epsilon_{(M,N)}=\id_{N\odot M} &\qquad \epsilon_{(N,M)}\circ \eta_{(M,N)}=\id_{U_{C}}
 \\
 \eta_{(M,N)}\circ \epsilon_{(N,M)}=\id_{M\odot N}&\qquad \epsilon_{(M,N)}\circ \eta_{(N,M)}=\id_{U_{{D}}}
\end{align*}

\label{defn:base_change_category}
 Let $F\colon  \scr{A} \to \scr{C}$ be a morphism in $\mathbf{Cat}(\scr{V})$, i.e. a functor of categories enriched in $\scr{V}$. Then there is an $(\scr{A}, \scr{C})$-bimodule $_F \scr{C}$ where the left action of $\scr{A}$ is given by
  \begin{align*}
  \scr{A}(a, a') \otimes ({_F \scr{C}})(a', c) 
   &= \scr{A}(a, a') \otimes \scr{C}(F(a'), c) 
  \\
  &\to \scr{C}(F(a), F(a')) \otimes \scr{C}(F(a'), c) \to \scr{C}(F(a), c) = {_F \scr{C}(a, c)} 
  \end{align*}
  There is a dual $(\scr{C}, \scr{A})$-bimodule that we denote $\scr{C}_F$.

\label{defn:twisted_loop_space}
  The \textbf{$f$-twisted Moore loop space} is the topological space 
  \[
  \Omega^M X^f = \{(\gamma, u) \in \scr{P}^M X : \gamma(0) = \ast, \gamma(u) = f(\ast)\}
  \]
  i.e. it is given as a pullback
  \[
  \xymatrix{
    \Omega^M X^f \ar[r]\ar[d] & \scr{P}^M X \ar[d]\\
    \ast \ar[r]^{\operatorname{id} \times f} & X \times X 
  }
  \]
  Again, $|\omega|$ denotes the length of the path $\omega$.

theorem.raw:
\label{base_change_one_object}
Let $\sC$ and $\sD$ be  categories enriched over $\sV$, $c$ be an object of $\scr{C}$, $d$ be an object of $\scr{D}$,  $\scr{M}$ be a right dualizable $(\sC,\sD)$-bimodule, 
and suppose $E_d$ is a Morita equivalence.  
Let $\scr{Q}$ be a $(\sC,\sC)$-bimodule, $\scr{P}$ be a $(\scr{D},\scr{D})$-bimodule
and 
\[
  \phi\colon \scr{Q}\odot \scr{M}\to \scr{M}\odot \scr{P} 
\] 
be a natural transformation.  Then 
\begin{equation}\label{eq:base_change_one_object}
 \xymatrix@C=70pt{
  \sh{_{E_c}\scr{Q}_{E_c}}\ar[d]^{\tr\left(\rbm{\epsilon}{E_c}{\scr{C}}{\scr{Q}}\right)}\ar[r]^-{\tr({_{E_c}\scr{C}}\odot \phi\odot\scr{D}_{E_d})}
  &\sh{_{E_d}\scr{P}_{E_d}}\ar[d]^{\tr\left(\rbm{\epsilon}{E_d}{\scr{D}}{\scr{P}}\right)}
  \\
  \sh{\scr{Q}}\ar[r]^-{\tr(\phi)}
  &\sh{\scr{P}}}
\end{equation}
commutes.

lemma.raw:
\label{lem:base_change_euler_ex}
Let $F\colon \sA\to \sC$ be a $\sV$-functor between $\sV$-categories  and $\scr{Q}$ be a $(\scr{C},\scr{C})$-bimodule.  
Then the following two diagrams commute.
\[\xymatrix@C=12pt{
  \coprod_{a}\scr{A}(a,a)\ar[d]\ar[r]^-F&\coprod _{a}\scr{C}(F(a),F(a))\ar[r]
  &\coprod _c\scr{C}(c,c)\ar[d]
  \\ 
  \sh{U_\scr{A}}\ar[rr]^{\chi_{({_F\sC},\sC_F)}(_F\scr{C})=\chi_{({_F\sC},\sC_F)}(\scr{C}_F)}
  && \sh{U_\scr{C}}
 }
 \hspace{3em}
 \xymatrix{
  \coprod_{a} \scr{Q}(F(a),F(a))\ar[r]\ar[d]
  &\coprod_{c} \scr{Q}(c,c)\ar[d]
   \\
  \sh{{_F\scr{Q}_F}}\ar[r]^-{\tr\left(\rbm{\epsilon}{F}{\scr{D}}{\scr{Q}}\right)}
  &\sh{\scr{Q}}
}\]

proposition.raw:
\cite[Appendix]{p:thesis}\cite[Lem.~7.6]{ps:indexed}\label{lem:base_change_euler}
\begin{enumerate}
  \item If $f\colon A\to C$ is a monoid homomorphism, $(_fC,C_f)$ is a dual pair.
  \item If $F\colon \sA\to \sC$ be a $\sV$-functor between $\sV$-categories, $({_F\sC},\sC_F)$ is a dual pair.
\end{enumerate}

\label{prop:main_prop} Suppose $f$, $j$, and $k$ are as above.   If $C_f$ is right dualizable then 
  the following diagram commutes. 
  \[
  \xymatrix@R=.5cm@C=1.5cm{
    \operatorname{THH}(C;C_k) \ar[r]^-{\tr\eqref{eq:main_base_change_map}}  \ar[d]^\sim& \operatorname{THH}(A; A_j)\ar[d]^\sim\\
    \operatorname{THH}(\operatorname{Mod}^c_C;- \wedge C_k) \ar[r]^-{\tr\eqref{eq:thh_twist_map}}  
  & \operatorname{THH}(\operatorname{Mod}^c_A ; -\wedge A_j).
    }
  \]

\label{prop:base_change_euler_monoid}
If $\scr{M}$ is a right dualizable $(\scr{C},\scr{D})$-bimodule  and $F\colon \scr{A}\to \scr{C}$ is an enriched functor, the trace of $\rbmm{\epsilon}{F}{\scr{C}}{{\scr{C}}}{\scr{M}}$ is the composite 
\[\sh{{_F\scr{C}_F}}\xrightarrow{\tr\left(\rbm{\epsilon}{F}{\scr{C}}{U_\scr{C}}\right)}
\sh{\scr{C}}\xrightarrow{\chi(\scr{M})} \sh{\scr{D}}.\]
If $\alpha \colon \scr{Q}\to {_F\scr{C}_F}$ is a map of $(\scr{A},\scr{A})$-{\bf bimodules} 
 the trace of 
$\scr{Q}\odot {_F\scr{M}}\xrightarrow{\alpha \odot \id_{{_F\scr{M}}}}{_F\scr{C}_F}\odot {_F\scr{M}}\xrightarrow{\rbmm{\epsilon}{F}{\scr{C}}{{\scr{C}}}{\scr{M}} } 
{_F\scr{M}}$
is 
\[\sh{\scr{Q}}\xrightarrow{\sh{\alpha}} \sh{ {_{F}\scr{C}_{F}}}\xrightarrow{\tr\left(\rbm{\epsilon}{F}{\scr{C}}{U_\scr{C}}\right)}\sh{\scr{C}}\xrightarrow{\chi(\scr{M})} \sh{\scr{D}}. \]

corollary.raw:
\label{euler_char_shadows_3}
If $L$ is right dualizable 
\[\xymatrix@C=50pt{
\sh{M_1\odot Q\odot N_1}\ar[r]^-{\tr(M_1\odot f\odot M_2)}\ar[d]_-{\tr\left( \rsm{\epsilon}{M_1}{N_1}{Q}\right)}
&\sh{N_2\odot P\odot M_2}
\\
\sh{Q}\ar[r]^-{\tr(f)}&\sh{P}\ar[u]_{\tr\left( \rsm{\eta}{M_2}{N_2}{P}\right)}
}\]
commutes.

\label{euler_char_shadows_4} 
Suppose  $(M_1,N_1)$ is a dual pair, $(M_2,N_2)$ is a Morita equivalence, $Q$ and $P$ are 1-cells so that 
$M_1\odot Q\odot N_1$ and $N_2\odot P\odot M_2$ are defined.  For a right dualizable 1-cell
$L$ so that $M_1\odot L\odot M_2$ is defined, and a 2-cell $f\colon Q\odot L\to L\odot P$ the following diagram commutes.
\[\xymatrix@C=50pt{
 \sh{M_1\odot Q\odot N_1}\ar[r]^-{\tr(M_1\odot f\odot M_2)}\ar[d]_-{\tr\left(\rsm{\epsilon}{M_1}{N_1}{Q} \right)}
 &\sh{N_2\odot P\odot M_2}\ar[d]^{\tr\left(\rsm{\epsilon}{N_2}{M_2}{P}\right) }
 \\
 \sh{Q}\ar[r]^-{\tr(f)}
 &\sh{P}
}\]

\label{cor:base_change_morita_isos}
If $F\colon \sA\to \sC$ is a Morita equivalence and $\scr{Q}$ is a $(\scr{C},\scr{C})$-bimodule 
\[
\sh{F} \colon \sh{\scr{A}}\to \sh{\scr{C}}
\quad\text{ and }\quad
\tr\left(\rbm{\epsilon}{F}{\scr{C}}{\scr{Q}}\right)\colon \sh{{_F\scr{Q}_F}}\rightarrow \sh{\scr{Q}}
\] 
are isomorphisms.

\label{cor:lind_malkiewich}
Let $\sA$ and $\sC$ be  categories enriched over $\sV$, $a$ be an object of $\scr{A}$, $c$ be an object of $\scr{C}$, and  $F\colon \sA\to \sC$ be a $\scr{V}$-functor. 
If  $E_c\colon \End_\scr{C}(c)\to \scr{C}$ is a Morita equivalence, 
\[\xymatrix@C=65pt{
 \sh{\End_\scr{A}(a)}\ar[d]^{\sh{E_a}}\ar[r]^-{\chi({_{F\circ E_a}\sC_{E_c}})}
 &\sh{\End_\scr{C}(c)}\ar[d]^{\sh{E_c}}
 \\
 \sh{\scr{A}}\ar[r]^-{\sh{F}}&\sh{\scr{C}}
}\]
commutes.

\label{ex:base_change_and_natural_transformation}
For $\scr{A}$, $\scr{C}$, $J$, $K$, $F$, $\phi$ and $\psi$ as above and objects $a$ of $\scr{A}$ and $c$ of $\scr{C}$, 
the following diagrams, where  vertical maps are induced by inclusions on hom sets, commute.
\[\xymatrix@C=60pt{
  \sh{\scr{A}(a,J(a))} \ar[d] \ar[r]^-{\tr\left({_{E_a}\scr{A}}\odot \phi\odot \scr{C}_{E_{c}}\right)}
  &\sh{\scr{C}(c,K(c))}\ar[d]
  \\
  \sh{\scr{A}_J}\ar[r]^-{\tr(\phi)}
  &\sh{\scr{C}_K}
  }
\hspace{10pt}

\xymatrix@C=5pt{
  \sh{\scr{A}(a,J(a))} \ar[d] \ar[rr]^-{\tr\left({_{E_a}\scr{A}}\odot \phi\odot \scr{C}_{E_{c}}\right)}
  &&\sh{\scr{C}(c,K(c))}\ar[d]
  \\
  \sh{\scr{A}_J}\ar[r]^-{\sh{\psi}}&\sh{_F\scr{C}\odot \scr{C}_K\odot \scr{C}_F}\ar[r] 
