\begin{defn} 
	A spectral category $\scr{C}$ is \textbf{pointwise cofibrant} if each mapping spectrum $\scr{C}(a, b)$ is cofibrant in the enriching category.
\end{defn}

\begin{defn}
	Let $\scr{C}$ be a spectral category. Then a $\scr{C}$\textbf{-module} is a spectral functor $\scr{C} \to \operatorname{Sp}$. 
\end{defn}

\begin{defn}
  A \textbf{$(\scr{C}, \scr{D})$-bimodule} is a functor $\scr{M}\colon  \scr{C}^{\text{op}} \sma \scr{D} \to \operatorname{Sp}$. That is, $\scr{M}$ is a collection of spectra $\scr{M}(c, d)$ for $c \in \scr{C}$, $d \in \scr{D}$ together with maps
  \begin{align*}
    &\scr{C}(c, c') \sma \scr{M}(c', d) \to \scr{M}(c, d)\\
    &\scr{M}(c, d) \sma \scr{D}(d,d') \to \scr{M}(c, d') 
  \end{align*}
  An $(\scr{C}, \scr{D})$-bimodule is {\bf pointwise cofibrant} if $\scr{M}(c, d)$ is cofibrant. A {\bf morphism} of $(\scr{C}, \scr{D})$-bimodules $\scr{M} \to \scr{M}'$ is a collection of maps $\scr{M}(c, d) \to \scr{M}'(c, d)$ which commute with the appropriate structure. 
\end{defn}

\begin{defn}\label{def:base_change}
  Let $F\colon  \scr{A} \to \scr{C}$ and  $G\colon  \scr{B} \to \scr{C}$ be functors between spectral categories. Define an $(\scr{A}, \scr{B})$-bimodule $ \ _F \scr{C}_G$ as follows. For objects $a\in \scr{A}$ and $b \in \scr{B}$
  \[
  \ _F \scr{C}_G (a, b) \coloneqq \scr{C}(F(a), G(b)).  
  \]
 The right action of $\scr{B}$ on $\ _F \scr{C}_G$ is given by the functor $G$:
  \begin{align*}
  \ _F \scr{C}_G(a, b) \sma \scr{B} (b, b') &= \scr{C}(F(a),G(b)) \sma \scr{B} (b, b') \to \scr{C}(F(a), G(b)) \sma \scr{C}(G(b), G(b'))\\ &\to \scr{C} (F(a), G(b')) = \ _F \scr{C}_G (a, b') 
  \end{align*}  The left action of $\scr{A}$ is similar.
\end{defn}

\begin{defn}\label{right_twisted}
  Let $\scr{C}$ be a pointwise cofibrant spectral category and $F\colon  \scr{C} \to \scr{C}$ be an endofunctor. We defined the \textbf{right twisted topological Hochschild homology} to be
  \[
  \operatorname{THH}(\scr{C}; F)\coloneqq\operatorname{THH}(\scr{C}; \scr{C}_F) 
  \]
\end{defn}

\begin{defn}[\cite{p:thesis}]\label{def:shadow}
  Let $\scr{B}$ be a bicategory.  A \textbf{shadow functor} for $\scr{B}$
  consists of functors
  \[
   \sh{-}\colon  \scr{B}(C,C) \to \mathbf{T}
  \]
  for each object $C$ of $\scr{B}$ and some fixed category $\mathbf{T}$, equipped
  with a natural isomorphism
  \[
   \theta\colon \sh{M\odot N}\xrightarrow{\cong} \sh{N\odot M}
  \]
  for $M\in \scr{B}(C, D)$ and $N\in \scr{B}(D, C)$ such that the following
  diagrams commute whenever they make sense:
  \[\xymatrix{
    \sh{(M\odot N)\odot P} \ar[r]^\theta \ar[d]_{\sh{a}} &
    \sh{P \odot (M\odot N)} \ar[r]^{\sh{a}} &
    \sh{(P\odot M) \odot N}
    \\
    \sh{M\odot (N\odot P)} \ar[r]^\theta 
    & \sh{(N\odot P)\odot M} \ar[r]^{\sh{a}} 
   & \sh{N\odot (P\odot M)}\ar[u]_\theta 
  }\]
  \[\xymatrix{
    \sh{M\odot U_C} \ar[r]^\theta \ar[dr]_{\sh{r}} &
    \sh{U_C\odot M} \ar[d]^{\sh{l}} \ar[r]^\theta &
    \sh{M\odot U_C} \ar[dl]^{\sh{r}}
    \\
    &\sh{M}}\]
\end{defn}

\begin{defn}We say that a 1-cell $M\in \scr{B}(C,D)$ in a bicategory is \textbf{right dualizable} if there is a 1-cell $N\in \scr{B}(D,C)$, called its \textbf{right dual}, and coevaluation and evaluation 2-cells $\eta\colon U_C \to M\odot N$ and $\epsilon \colon N\odot M\to U_D$ satisfying the triangle identities.
We  say that $(M,N)$ is a \textbf{dual pair}, that $N$ is \textbf{left dualizable}, and that $M$ is its \textbf{left dual}.
\end{defn}

\begin{defn}\cite{p:thesis}\label{defn:trace}
  Let $\scr{B}$ be a bicategory with a shadow functor and $(M,N)$ be a dual pair.
  The \textbf{trace} of a 2-cell $f\colon Q\odot M\rightarrow M\odot P$ is the composite:
  \[
   \sh{Q}\cong \sh{Q\odot U_C}\xrightarrow{\sh{\id_Q\odot\eta}}
  \sh{Q\odot M\odot N} \xrightarrow{\sh{f\odot\id_N}}
  \sh{M\odot P\odot N} \xrightarrow{\theta}
  \sh{N\odot M\odot P} \xrightarrow{\sh{\epsilon \odot \id_P}}
  \sh{U_D\odot P}\cong   \sh{P}.
  \]
The trace of a 2-cell $g\colon N\odot Q\to P\odot N$ is 
  \[
   \sh{Q}\cong \sh{U_C\odot Q}\xrightarrow{\sh{\eta\odot\id_Q}}
  \sh{M\odot N\odot Q} \xrightarrow{\sh{\id_M\odot g}}
  \sh{M\odot P\odot N} \xrightarrow{\theta}
  \sh{P\odot N\odot M} \xrightarrow{\sh{\id_P \odot \epsilon}}
    \sh{P\odot U_D}\cong   \sh{P}.
  \]
\end{defn}

\begin{defn}\label{defn:euler_characteristic}
  If $M\in \scr{B}(C,D)$ and $M$ is right dualizable, the \textbf{Euler characteristic} (\cref{fig:euler_char}) is the trace of the identity 2-cell of $M$ and is a map \[\sh{U_C}\to \sh{U_D}.\]   
If $N$ is the right dual of $M$, $\chi(M)=\chi(N)$.
\end{defn}

\begin{defn}\label{defn:morita_equivalence}
A pair of one cells $M\in \scr{B}(C,D)$ and $N\in \scr{B}(D,C)$ is a {\bf Morita equivalence} if $(M,N)$ and $(N,M)$ are dual pairs and
the coevaluation and evaluation maps for each dual pair are inverses.  That is, if $\eta_{(M,N)}$ and $\epsilon_{(M,N)}$ are the coevaluation and evaluation 
for $(M,N)$ and $\eta_{(N,M)}$ and $\epsilon_{(N,M)}$ are the coevaluation and evaluation 
for $(N,M)$ then
\begin{align*}
 \eta_{(N,M)}\circ \epsilon_{(M,N)}=\id_{N\odot M} &\qquad \epsilon_{(N,M)}\circ \eta_{(M,N)}=\id_{U_{C}}
 \\
 \eta_{(M,N)}\circ \epsilon_{(N,M)}=\id_{M\odot N}&\qquad \epsilon_{(M,N)}\circ \eta_{(N,M)}=\id_{U_{{D}}}
\end{align*}
\end{defn}

\begin{defn}
If $M \in \scr{B}(C, D)$ and $N \in \scr{B}(D, C)$ define a Morita equivalence, then $C$ and $D$ are said to be \textbf{Morita equivalent}. 
\end{defn}

\begin{defn}\label{defn:base_change_monoid}
 Let $f\colon  A \to C$ be a morphism in $\mathbf{Mon}(\scr{V})$. Then there is an $(A, C)$-bimodule  $ _f C$, which is $C$ with a left $A$-action given by $f$,  and a $(C, A)$-bimodule $C_f$ which is $C$ with a right $A$-action given by $f$.
\end{defn}

\begin{defn}\label{defn:base_change_category}
