\end{defn}

\begin{defn}\label{defn:base_change_monoid}
 Let $f\colon  A \to C$ be a morphism in $\mathbf{Mon}(\scr{V})$. Then there is an $(A, C)$-bimodule  $ _f C$, which is $C$ with a left $A$-action given by $f$,  and a $(C, A)$-bimodule $C_f$ which is $C$ with a right $A$-action given by $f$.
\end{defn}

\begin{defn}\label{defn:base_change_category}
 Let $F\colon  \scr{A} \to \scr{C}$ be a morphism in $\mathbf{Cat}(\scr{V})$, i.e. a functor of categories enriched in $\scr{V}$. Then there is an $(\scr{A}, \scr{C})$-bimodule $_F \scr{C}$ where the left action of $\scr{A}$ is given by
  \begin{align*}
  \scr{A}(a, a') \otimes ({_F \scr{C}})(a', c) 
   &= \scr{A}(a, a') \otimes \scr{C}(F(a'), c) 
  \\
  &\to \scr{C}(F(a), F(a')) \otimes \scr{C}(F(a'), c) \to \scr{C}(F(a), c) = {_F \scr{C}(a, c)} 
  \end{align*}
  There is a dual $(\scr{C}, \scr{A})$-bimodule that we denote $\scr{C}_F$. 
\end{defn}

\begin{defn}
We call any of $_f C$, $C_f$, $_F \scr{C}$, $\scr{C}_F$ \textbf{base change 1-cells}.
\end{defn}

\begin{defn}
If $\scr{C}$ is a category enriched in $\scr{V}$ and $c$ is an object of $\scr{C}$ let $\End_\scr{C}(c)$ denote the  full subcategory of $\scr{C}$ whose single object is $c$.  
Let $E_c\colon \End_\scr{C}(c)\to \scr{C}$ be the inclusion.
\end{defn}

\begin{defn}
If $\scr{M}$ is an $(\scr{C},\scr{D})$-bimodule  and $F\colon \scr{A}\to \scr{C}$ is a functor 
let $\rbmm{\epsilon}{F}{\scr{C}}{{\scr{C}}}{\scr{M}}$ be the $(\scr{A},\scr{D})$-bimodule map given by  composite 
\[_F\scr{C}_F\odot {_F\scr{M}}\xleftarrow{\id_{_F\scr{C}_F}\odot \sim } {_F\scr{C}_F}\odot {_F\scr{C}}\odot \scr{M} \xrightarrow{\rbm{\epsilon}{F}{\scr{C}}{U_{\scr{C}}}\odot \id_\scr{M}} {_F\scr{C}}\odot \scr{M}
\xrightarrow{\sim } {_F\scr{M}}\]
This map is induced by the action of $\scr{C}$ on $\scr{M}$ restricted to the objects in the image of $F$.
\end{defn}

\begin{defn}
  Let $X$ be a based space with base $\ast$. Then the \textbf{Moore loop space} is 
  \[
  \Omega^M X = \{(\gamma, u) \in \scr{P}^M X : \gamma(0) = \gamma(u) = \ast\} 
  \]
  that is, it is the pullback
  \[
  \xymatrix{
    \Omega^M X \ar[r]\ar[d] & \scr{P}^MX \ar[d]^{s \times t} \\
    \ast\ar[r]  & X \times X 
  }
  \]
  For work below, it is convenient to denote the ``length'' of the path, $u$, by $|\omega|$. 
\end{defn}

\begin{defn}\label{defn:twisted_loop_space}
  The \textbf{$f$-twisted Moore loop space} is the topological space 
  \[
  \Omega^M X^f = \{(\gamma, u) \in \scr{P}^M X : \gamma(0) = \ast, \gamma(u) = f(\ast)\}
  \]
  i.e. it is given as a pullback
  \[
  \xymatrix{
    \Omega^M X^f \ar[r]\ar[d] & \scr{P}^M X \ar[d]\\
    \ast \ar[r]^{\operatorname{id} \times f} & X \times X 
  }
  \]
  Again, $|\omega|$ denotes the length of the path $\omega$. 
\end{defn}

\begin{defn}
 The topological space $(\scr{L} X^f)^{\Delta^n}$ is defined to be 
  \[
  (\scr{L} X^f)^{\Delta^n} = \left\{\gamma \in \operatorname{Map}(\Delta^n, \scr{P} X)\biggr|\begin{matrix} \gamma_{u_0, \dots, u_n} (0) = f (\gamma_{u_0, \dots, u_n} (1)) \\ \text{for all}\ (u_0, \dots, u_n) \in \Delta^n \end{matrix}\right\} 
  \]
Again, the cosimplicial structure on $\Delta^\bullet$ induces a simplicial structure on $(\scr{L} X^f)^{\Delta^\bullet}$. The face and degeneracy maps are as above. 
\end{defn}

