The following is a crucial example. It is a classical fact for rings \cite[Prop.~2.1.5]{dundas_mccarthy}, and known for spectra \cite{blumberg_mandell} and it provides important motivation for this paper. The example shows that it follows from purely bicategorical facts.


\begin{example}\label{spectral_category_morita_equivalence}
  Let $\scr{B}(\mathbf{Cat}(\operatorname{Sp}))$ be the bicategory of spectral categories (with the proper homotopy theoretic considerations, see \cref{bcat_example}) . Let $A$ be a ring spectrum. There are two spectral categories naturally associated with $A$
  \begin{enumerate}
  \item The spectral category $\operatorname{Mod}^c_A$. 
  \item The one object spectral category whose hom spectrum is $A$.  We denote this category $\End_{ \operatorname{Mod}^c_A}(A)$ since it is the full subcategory of  $\operatorname{Mod}^c_A$ with the single object $A$.
  \end{enumerate}
There is an inclusion functor 
\[
  E_A\colon  \End_{ \operatorname{Mod}^c_A}(A) \to \Mod^c_A
\] 
and so we can construct a 1-cell (i.e. a spectral bimodule) $ _{E_A} (\operatorname{Mod}^c_A)$. There is similarly a spectral bimodule  $ (\Mod^c_A)_{E_A}$. These two bimodules are a Morita equivalence.

Applying \cref{cor:base_change_morita_isos} with the substitutions
\begin{center}
  \begin{tabular}{c|c|c}
    $\scr{A}$ & $\scr{C}$ & $F$\\\hline
    $\End_{\operatorname{Mod}^c_A} (A)$ & $\Mod^c_A$ & $E_A$
  \end{tabular}
\end{center}
the map 
\begin{equation}\label{eq:thh_A_mod}
  \operatorname{THH}(A) \cong \operatorname{THH}\left(\End_{\Mod^c_A} (A)\right) \to \operatorname{THH}\left(\Mod^c_A\right)
\end{equation} 
induced by the inclusion of $A$ into $\Mod^c_A$ as a module over itself is an isomorphism.
We will give an explicit description of the inverse of this map on $\pi_0$ in \cref{lem:base_change_euler_inverse}.
\end{example}

\begin{example}\label{ex:twist_thh_morita}
Let $A$ be a ring spectrum,  $Q$ be an $(A,A)$-bimodule, and  
\[
-\sma_AQ\colon  \operatorname{Mod}^c_A \to \operatorname{Mod}^c_A
\] 
be given by $M \mapsto M \sma_A Q$.  Then $(\operatorname{Mod}^c_A)_{-\sma_AQ}$ is 
an  $(\operatorname{Mod}^c_A, \operatorname{Mod}^c_A)$-bimodule and the inclusion 
\[
  E_A\colon  \End_{ \operatorname{Mod}^c_A}(A) \to \operatorname{Mod}^c_A
\] 
defines a $(\End_{ \operatorname{Mod}^c_A}(A),\End_{ \operatorname{Mod}^c_A}(A))$-bimodule  $_{E_A}((\operatorname{Mod}^c_A)_{-\sma_AQ})_{E_A}$.  

Since $E_A$ is a Morita equivalence, applying \cref{cor:base_change_morita_isos} with the substitutions 
\begin{center}
\begin{tabular}{c|c|c|c}
$\scr{A}$
&$\scr{C}$
&$F$
&$\scr{Q}$
\\
\hline
$\End_{\operatorname{Mod}^c_A}(A)$
&$\operatorname{Mod}^c_A$
&$E_A$
&$(\operatorname{Mod}^c_A)_{-\sma_AQ}$
\end{tabular}
\end{center}
gives an isomorphism $\sh{_{E_A}((\operatorname{Mod}^c_A)_{-\sma_AQ})_{E_A}} \to \sh{(\operatorname{Mod}^c_A)_{-\sma_AQ}}$. We also have identifications
  \begin{align*}
    & \sh{ {_{E_A}( (\operatorname{Mod}^c_A)_{-\sma_AQ}})_{E_A}} = \sh{Q} = \operatorname{THH}(A; Q)\\
    &\sh{(\operatorname{Mod}^c_A)_{-\sma_AQ}} = \sh{(\operatorname{Mod}^c_A)_{-\sma_AQ}} = \operatorname{THH}(\operatorname{Mod}^c_A ; {-\sma_AQ}) 
  \end{align*}
  and so an isomorphism
  \[
  \operatorname{THH}(A; Q)\to \operatorname{THH}(\operatorname{Mod}^c_A; {-\sma_AQ})
  \]
  Thus, the classical Morita invariance of $\operatorname{THH}$ holds in a twisted context as well. 
\end{example}

