 &&&\sh{_{E_d}\scr{P}_{E_d}}\ar[d]^{\tr\left(\rbm{\epsilon}{E_d}{\scr{D}}{\scr{P}}\right)}
 \\
 \sh{\scr{Q}}\ar[r]^-{\sh{\psi}}
 &\sh{\scr{M}\odot \scr{P}\odot \scr{N}}\ar[rr]^-{\tr\left(\rsm{\epsilon}{\scr{M}}{\scr{N}}{\scr{P}}\right )} 
