 }
\end{equation}

An important example of this is the 2-cells that arise from a natural transformation as in \cref{ex:base_change_and_natural_transformation}.  We first describe how these two cells are defined.
For enriched categories  $\scr{A}$ and $\scr{C}$,  enriched functors
\[
J\colon \scr{A}\to\scr{A}, K\colon \scr{C}\to \scr{C}\text{ and }F\colon \scr{A}\to \scr{C},
\]
 and a natural transformation $\Phi\colon F\circ J\to K\circ F$
let
$\phi\colon \scr{A}_{J}\odot {_F\scr{C}} \to {_F\scr{C}\odot\scr{C}_K }$ be the 2-cell defined by 
\begin{align*}
 (a\xrightarrow{\alpha}J(a'),F(a')\xrightarrow{\beta}c)&\mapsto (F(a)\xrightarrow{F(\alpha)}F(J(a'))\xrightarrow{ \Phi_{a'}}K(F(a'))\xrightarrow{K(\beta)}K(c))
\end{align*} 
and $\psi\colon \scr{A}_J\to{_F\scr{C}\odot \scr{C}_K\odot \scr{C}_F} $ be 2-cell defined by 
\[
 (a\xrightarrow{\alpha} J(a'))\mapsto  (F(a)\xrightarrow{F(\alpha)}F(J(a'))\xrightarrow{\Phi_{a'}}K(F(a')))
\]
This choice of $\phi$ and $\psi$ are related as in \eqref{switch_for_trace}.

\begin{proof} 
