  \ar[d]^{\tr\left(\rbm{\epsilon}{E_a}{\scr{A}}{\scr{A}_J}\right)}
  \ar[r]^-{\tr\left({_{E_a}\scr{A}}\odot \phi\odot \scr{C}_{E_{c}}\right)}
 &\sh{_{E_{c}}(\scr{C}_K)_{E_{c}}}\ar[d]^{\tr\left(\rbm{\epsilon}{E_{c}}{\scr{C}}{\scr{C}_K}\right)}
 \\
