\] and 
 induces maps 
\begin{gather}\label{eq:main_base_change_map} C_k\odot C_f\to C_f\odot A_j.
\\
\label{eq:thh_twist_map}
(\Mod_C^c)_{-\wedge_CC_k}\odot {_{-\wedge_CC_f}(\Mod_A^c)}\to 
{_{-\wedge_CC_f}(\Mod_A^c)}\odot (\Mod_A^c)_{-\wedge_AA_j}
\end{gather}

Recall that twisted $\operatorname{THH}$ was defined in \cref{right_twisted}, and $\scr{L}X^f$ in the introduction --- but see also \cref{defn:twisted_loop_space}. 

\begin{proof}
In \cite[Prop.~3.2.3]{p:thesis} the Reidemeister trace of the introduction is identified with a bicategorical trace.  This trace is identified with a more homotopically satisfying trace in 
\cite[Prop.~6.2.2]{p:thesis} and finally identified with a trace in the parameterized stable homotopy bicategory,  $\operatorname{Ex}$, in \cite[Thm.~4.1]{p:coincidence}.  

In the bicategory of parameterized spectra, let $S_X$ denote the fiberwise suspension spectrum of $X$ regarded as a space over $\ast\times X$ via the identity map.  If $f\colon X\to X$ is a continuous map $X_f$ is the  fiberwise suspension spectrum of  $\{(\gamma,x)\in X^I\times X|\gamma(1)=f(x)\}$
regarded as a space over $X\times X$ via the map $(\gamma,x)\mapsto (\gamma(0),x)$.
Then $f$ defines a map of spectra
\begin{equation}\label{twisted_map_of_X_f} 
S \odot S_X \to S_X \odot X_f
\end{equation}
If $X$ is a closed smooth manifold, $S_X$ is right dualizable and the trace of \eqref{twisted_map_of_X_f} 
is a map $\sh{S}\to \sh{X_f}$.  This map is one form of the Reidemeister trace.

Now, we use the Morita equivalence of \cite{lind_malkiewich_morita} to compare the shadows in $\operatorname{Ex}(X, X)$ and $(\Sigma^\infty_+ \Omega X, \Sigma^\infty_+ \Omega X)$-bimodules. Let $\scr{B}\text{imod}_S$ be the bicategory of ring spectra and spectral bimodules, and $\scr{B}\text{imod}^{\text{gp}}_S$ be the full-subcategory of ring spectra of the form $\Sigma^\infty_+ \Omega X$.  Then, \cite[Thm.~6.4]{lind_malkiewich_morita} as applied in \cite[Thm.~5.1]{lind_malkiewich} gives that the parameterized stable homotopy bicategory (when restricted to connected spaces) and $\scr{B}\text{imod}^{\text{gp}}_S$ are bicategorically equivalent with an induced equivalence on shadows. Under this equivalence (given in detail before \cite[Thm.~5.1]{lind_malkiewich}) the map of parameterized spectra in \eqref{twisted_map_of_X_f}  passes to the map of $(S, \Sigma^\infty_+ \Omega X)$-bimodule spectra 
\begin{equation}\label{Reidemeister_map_of_modules}
S \sma_{S} \Sigma^\infty_+ \Omega X \to \Sigma^\infty_+\Omega X \sma_{\Sigma^\infty_+ \Omega X} \Sigma^\infty_+ \Omega X_f.
\end{equation}
The functoriality of the trace \cite{p:thesis} implies the following diagram  commutes.
\[
\xymatrix@C=40pt{
  \sh{S} \ar[d]^{\sim}\ar[r]^{\tr\eqref{twisted_map_of_X_f} } & \sh{X_f}\ar[d]^{\sim} \\
  \sh{S}\ar[r]^-{\tr\eqref{Reidemeister_map_of_modules}} & \sh {\Sigma^\infty_+ \Omega X_f}.
}
\]

Then \cref{prop:main_prop} implies
\[
\xymatrix{
  \sh{S} \ar[d]^{\sim}\ar[r]^-{\tr\eqref{Reidemeister_map_of_modules}}  & \sh {\Sigma^\infty_+ \Omega X_f}\ar[d]^{\sim}\\
  \operatorname{THH}(\operatorname{Mod}^c_S) \ar[r] & \operatorname{THH}(\operatorname{Mod}^c_{\Sigma^\infty_+ \Omega X}; -\wedge \Sigma^\infty_+ \Omega X_f)
}
\]
commutes and 
\cref{cor:identify_thh_loop} identifies \[\operatorname{THH}(\Sigma^\infty_+\Omega X; \Sigma^\infty_+ \Omega X_f)\simeq \Sigma^\infty_+ \scr{L} X^f .\qedhere\]
\end{proof}

