	\quad \text{and } \quad 
	\sh{M\odot P\odot N}\xrightarrow{\tr\left(\rsm{\epsilon}{M}{N}{P}\right)=\tr\left(\lsm{\epsilon}{M}{N}{P}\right)} \sh{P}
\end{gather*}

